head.script:
scwin.trigger1_onclick = function(e) {
    scvar.fn_listToggle(true);
};
scwin.trigger2_onclick = function(e) {
    scvar.fn_listToggle(false);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grd_list_cell_2_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grd_list_cell_17_1').style.backgroundColor == 'rgb(255, 128, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    for (var idx = 0; idx < 40; idx++) {
        dl_list.insertRow(idx);
    };
    window.scvar = {};
    scwin.toggleObj = {
        height: ['600', '127']
    };
    /**
     * 목록 더보기, 상세보기 등 화면 처리한다.
     *
     * @param <object> obj.grp 숨겨질 그룹
     * @param <object> obj.btn 버튼
     * @param <object> obj.grd 그리드
     * @param <Array> obj.btnTxt 버튼 텍스트
     * @param <Array> obj.height 그리드 높이
     * @param <number> obj.rowIdx 포커스 행 인덱스
     * @param <number> obj.colIdx 포커스 열 인덱스
     * @date 2018. 09. 05
     */
    scvar.fn_toggle = function(obj) {
        //debugger;
        window.grp = obj.grp || WebSquare.wUnit.getJq('#grp_detail');
        window.btn = obj.btn || trigger1;
        window.id = btn.getID();
        window.grd = obj.grd || grd_list;
        window.btnTxt = obj.btnTxt || ['상세정보 보기', '상세정보 닫기'];
        if (scwin.toggleObj.toggleFlag) {
            WebSquare.wUnit.getJq('#' + id).removeClass('down').addClass('up');
            grp.hide();
            //btn.setValue(btnTxt[0]);
            grd.setGridHeight(scwin.toggleObj.height[0]);
            obj.toggleFlag = true;
            //debugger;
            console.log("down    " + scwin.toggleObj.rowIdx + " //  " + scwin.toggleObj.colIdx);
            grd.setFocusedCell(scwin.toggleObj.rowIdx, scwin.toggleObj.colIdx, true); //false
        } else {
            WebSquare.wUnit.getJq('#' + id).removeClass('up').addClass('down');
            grp.show();
            //btn.setValue(btnTxt[1]);
            grd.setGridHeight(scwin.toggleObj.height[1]);
            obj.toggleFlag = true;
            console.log("up    " + scwin.toggleObj.rowIdx + " //  " + scwin.toggleObj.colIdx);
            grd.setFocusedCell(scwin.toggleObj.rowIdx, scwin.toggleObj.colIdx, true);
        }
        return obj.toggleFlag;
    };
    scvar.fn_listToggle = function(flag) {
        //debugger;
        scwin.toggleObj.rowIdx = grd_list.getFocusedRowIndex();
        scwin.toggleObj.colIdx = grd_list.getFocusedColumnIndex();
        scwin.toggleObj.toggleFlag = flag;
        scwin.toggleFlag = scvar.fn_toggle(grd_list);
    };
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
